args.new:
words = text.split()
result = []
is_first_word = True
for word in words:
    lower = word.lower()
    if lower in SMALL_WORDS:
        if is_first_word:
            result.append(lower.capitalize())
            is_first_word = False
        else:
            result.append(lower)
    else:
        result.append(lower.capitalize())
return " ".join(result)
